class SimpleReflexAgent:
    def select_action(self, location: str, status: str) -> str:
        if status == 'DIRTY':
            return 'SUCK'
        elif location == 'A':
            return 'RIGHT'
        elif location == 'B':
            return 'LEFT'
        return 'NOOP'

agent = SimpleReflexAgent()
print('Action when dirty in Room A:', agent.select_action('A', 'DIRTY'))
print('Action when clean in Room A:', agent.select_action('A', 'CLEAN'))
